Here’s the Rust implementation:

```rust
use std::collections::{BinaryHeap, HashMap};
use std::cmp::Reverse;

struct GridMaster; // This is just a placeholder for the actual provided interface

impl GridMaster {
    fn can_move(&self, dir: char) -> bool {
        // Implementation is hidden in the problem
        unimplemented!()
    }
    fn move_robot(&self, dir: char) -> i32 {
        // Implementation is hidden in the problem
        unimplemented!()
    }
    fn is_target(&self) -> bool {
        // Implementation is hidden in the problem
        unimplemented!()
    }
}

struct Solution;

impl Solution {
    pub fn find_shortest_path(master: &GridMaster) -> i32 {
        let dirs = [('U', -1, 0), ('D', 1, 0), ('L', 0, -1), ('R', 0, 1)];
        let opposite = [('U', 'D'), ('D', 'U'), ('L', 'R'), ('R', 'L')]
            .iter()
            .cloned()
            .collect::<HashMap<_, _>>();

        let mut cells = HashMap::new();
        let mut target = None;

        // DFS to explore the grid
        fn dfs(
            r: i32,
            c: i32,
            master: &GridMaster,
            cells: &mut HashMap<(i32, i32), (i32, bool)>,
            dirs: &[(char, i32, i32)],
            opposite: &HashMap<char, char>,
        ) {
            // Check if current cell is target
            let is_target = master.is_target();
            // We don't know cost of current cell until we move into it, but here we are already in it.
            // Actually, we need to store cost of this cell from when we moved into it.
            // So cost should be passed from caller.
            // Let's redesign: store (cost, is_target) for each cell.
            // But cost is only known when we move into it, so we store it in the map before DFS.
            // The starting cell cost is 0? No, starting cell cost is not applied until we move into it.
            // Actually, starting cell's cost is not paid at start, so for Dijkstra we treat start cost as 0.
            // But for other cells, cost is the cost to step onto them.

            // We'll store cost in the map during move.
            // This is tricky: We are in cell (r, c) now, but we don't have its cost unless we moved into it.
            // So we need to pass cost from parent.

            // Let's change approach: In DFS, when we move to a new cell, we get its cost from move_robot,
            // store it, then DFS, then move back.
        }

        // Better: iterative DFS with stack to avoid recursion depth issues
        let mut stack = vec![(0, 0, 0, false)]; // (r, c, cost_to_enter, is_target)
        cells.insert((0, 0), (0, master.is_target()));
        if master.is_target() {
            target = Some((0, 0));
        }

        let mut visited_dfs = HashMap::new();
        visited_dfs.insert((0, 0), true);

        // We'll use a manual stack for DFS
        let mut stack = vec![(0, 0)];
        while let Some((r, c)) = stack.pop() {
            for &(dir, dr, dc) in &dirs {
                let nr = r + dr;
                let nc = c + dc;
                if !visited_dfs.contains_key(&(nr, nc)) && master.can_move(dir) {
                    let cost = master.move_robot(dir);
                    let is_target = master.is_target();
                    cells.insert((nr, nc), (cost, is_target));
                    if is_target {
                        target = Some((nr, nc));
                    }
                    visited_dfs.insert((nr, nc), true);
                    stack.push((nr, nc));
                    // Move back
                    let opp = opposite[&dir];
                    master.move_robot(opp);
                }
            }
        }

        // Now we have cells map: (r, c) -> (cost, is_target)
        // Run Dijkstra from (0, 0) to target
        let mut dist = HashMap::new();
        let mut heap = BinaryHeap::new();
        dist.insert((0, 0), 0);
        heap.push(Reverse((0, 0, 0))); // (total_cost, r, c)

        while let Some(Reverse((total_cost, r, c))) = heap.pop() {
            if let Some(&(_, is_target)) = cells.get(&(r, c)) {
                if is_target {
                    return total_cost;
                }
            }
            if total_cost > *dist.get(&(r, c)).unwrap_or(&i32::MAX) {
                continue;
            }
            for &(_, dr, dc) in &dirs {
                let nr = r + dr;
                let nc = c + dc;
                if let Some(&(cost, _)) = cells.get(&(nr, nc)) {
                    let next_cost = total_cost + cost;
                    if next_cost < *dist.get(&(nr, nc)).unwrap_or(&i32::MAX) {
                        dist.insert((nr, nc), next_cost);
                        heap.push(Reverse((next_cost, nr, nc)));
                    }
                }
            }
        }

        -1
    }
}
```

**Explanation of the approach:**  
- We treat the starting cell as `(0, 0)` and explore all reachable cells using DFS, storing each cell’s **entry cost** and whether it’s the target.  
- During DFS, after moving to a new cell, we immediately move back to maintain the robot’s position for further exploration.  
- Once the map is built, we run Dijkstra’s algorithm from `(0, 0)` to find the minimum cost to reach any cell marked as target.  
- The starting cell’s cost is not added at the beginning (as per problem statement), so Dijkstra starts with total cost 0 at `(0, 0)`.  
- If the target is unreachable in the discovered graph, return `-1`.  

This method respects the hidden grid constraints and finds the minimum cost path using the robot’s interactive functions.

