```python
import re

def count_consonants(sentences):
    total_consonants = 0
    consonants = 'bcdfghjklmnpqrstvwxyz'
    vowels = 'aeiou'
    to_be_removed = []

    # Identify sentences to be removed
    for sentence in sentences:
        words = sentence.lower().split()

        # First filter: sentence length and starting/ending conditions
        if len(words) < 5 or words[0][0] in vowels or words[-1][-1] not in consonants:
            to_be_removed.append(sentence)
            continue

        # Check for palindromes or vowel-heavy words
        for word in words:
            if (word == word[::-1]) or (sum(word.count(vowel) for vowel in vowels) > 2):
                to_be_removed.append(sentence)
                break

        # Check for anagrams within the sentence
        for i in range(len(words)):
            for j in range(i + 1, len(words)):
                if sorted(words[i]) == sorted(words[j]):
                    to_be_removed.append(sentence)
                    break
            else:
                continue
            break

    # Removing unwanted sentences
    for sentence in to_be_removed:
        if sentence in sentences:
            sentences.remove(sentence)

    # Now count consonants in remaining sentences
    for sentence in sentences:
        words = re.sub(r'\W+', ' ', sentence).lower().split()
        for word in words:
            for char in word:
                if char in consonants:
                    total_consonants += 1

    return total_consonants
```

The approach here seems to be filtering out sentences that:
1. Are too short
2. Start with vowels or don't end with consonants
3. Contain palindromes or words with many vowels
4. Have anagram pairs

