```java
package com.example.ecommerce.domain;

import java.time.LocalDateTime;
import java.util.Objects;

/**
 * 核心业务领域对象：产品。
 * 体现了封装、不变性、验证和丰富的业务行为。
 * 这是系统业务逻辑的承载单元，而非简单的数据容器。
 */
public class Product {
    // ------------------ 核心属性（状态）--------------------
    // 使用 `final` 确保关键业务标识在对象生命周期内不变，增强可靠性和线程安全性
    private final String id; // 唯一业务标识，通常由系统生成
    private final String sku; // 库存单位码，业务唯一标识

    private String name;
    private String description;
    private double price;
    private int stockQuantity;
    private boolean active;
    private final LocalDateTime createdAt; // 记录创建时间，用于审计和追踪
    private LocalDateTime lastUpdatedAt;

    // ------------------ 静态常量（业务规则）----------------
    // 将分散的业务规则集中管理，便于维护和调整
    public static final double MIN_PRICE = 0.01;
    public static final int MIN_STOCK = 0;
    public static final int LOW_STOCK_THRESHOLD = 10;

    // ------------------ 构造函数（对象创建策略）-------------
    // 提供多种创建路径，满足不同业务场景，并确保对象始终处于有效状态

    /**
     * 全参数构造函数 - 用于从持久层（如数据库）完整加载对象
     * 通常由框架（如JPA/Hibernate）或仓库类调用
     */
    public Product(String id, String sku, String name, String description, 
                   double price, int stockQuantity, boolean active,
                   LocalDateTime createdAt, LocalDateTime lastUpdatedAt) {
        // 委托给核心验证逻辑，避免代码重复
        this(id, sku, name, description, price, stockQuantity);
        this.active = active;
        this.createdAt = Objects.requireNonNull(createdAt, "创建时间不能为null");
        this.lastUpdatedAt = lastUpdatedAt; // 允许为null（新对象）
    }

    /**
     * 核心业务构造函数 - 用于创建新的有效产品（如管理员后台操作）
     * 强制执行所有关键业务规则，是创建“合法”产品的唯一入口
     */
    public Product(String sku, String name, String description, double price, int initialStock) {
        // 生成ID（实际中可能使用UUID或数据库序列）
        this(java.util.UUID.randomUUID().toString(), sku, name, description, price, initialStock);
    }

    /**
     * 私有核心构造函数 - 集中所有基础验证逻辑
     * 体现了“创建即有效”的设计原则
     */
    private Product(String id, String sku, String name, String description, double price, int stockQuantity) {
        // 防御性编程：验证输入，防止垃圾数据进入系统
        this.id = Objects.requireNonNull(id, "产品ID不能为null");
        this.sku = validateSku(Objects.requireNonNull(sku, "SKU不能为null"));
        this.name = validateName(name);
        this.description = description != null ? description : ""; // 提供默认值
        this.price = validatePrice(price);
        this.stockQuantity = validateStock(stockQuantity);
        this.active = true; // 新产品默认激活
        this.createdAt = LocalDateTime.now(); // 记录对象创建时间点
        this.lastUpdatedAt = null; // 新创建，尚未更新
    }

    // ------------------ 核心业务方法（行为）-----------------
    // 对象不仅拥有数据，更拥有行为，这是与简单数据类的本质区别

    /**
     * 核心业务操作：减少库存。
     * 封装了库存扣减的完整逻辑，包括验证和状态更新。
     * @param quantity 要扣减的数量
     * @return 更新后的库存量
     * @throws IllegalArgumentException 如果扣减数量无效或库存不足
     * @throws IllegalStateException 如果产品未激活
     */
    public int reduceStock(int quantity) {
        // 前置条件检查
        if (!active) {
            throw new IllegalStateException("无法对已下架的产品进行库存操作。产品SKU: " + sku);
        }
        if (quantity <= 0) {
            throw new IllegalArgumentException("扣减数量必须为正数。请求数量: " + quantity);
        }
        if (quantity > stockQuantity) {
            throw new IllegalArgumentException(
                String.format("库存不足。当前库存: %d, 请求数量: %d", stockQuantity, quantity)
            );
        }

        // 执行业务操作
        stockQuantity -= quantity;
        updateTimestamp();

        // 后置条件：触发低库存事件（此处为日志，实际可发布领域事件）
        if (stockQuantity <= LOW_STOCK_THRESHOLD) {
            System.out.printf("[业务提醒] 产品 '%s' (SKU: %s) 库存偏低，当前数量：%d%n", 
                              name, sku, stockQuantity);
            // 实际场景：eventPublisher.publish(new LowStockEvent(this));
        }
        return stockQuantity;
    }

    /**
     * 核心业务操作：增加库存（补货）。
     */
    public int replenishStock(int quantity) {
        if (quantity <= 0) {
            throw new IllegalArgumentException("补货数量必须为正数。数量: " + quantity);
        }
        stockQuantity += quantity;
        updateTimestamp();
        return stockQuantity;
    }

    /**
     * 更新产品价格。价格调整可能涉及复杂的业务规则（如审计、价格历史）。
     */
    public void updatePrice(double newPrice) {
        this.price = validatePrice(newPrice);
        updateTimestamp();
        System.out.printf("[价格更新] 产品 '%s' 价格已从 %.2f 调整为 %.2f%n", 
                          name, price, newPrice);
    }

    /**
     * 激活/停用产品。这是一个重要的业务状态变更。
     */
    public void setActive(boolean active) {
        // 可以在此处添加更复杂的逻辑，如停用前检查是否有未完成订单
        boolean changed = this.active != active;
        this.active = active;
        if (changed) {
            updateTimestamp();
            String status = active ? "已激活" : "已停用";
            System.out.printf("[状态变更] 产品 '%s' (SKU: %s) %s%n", name, sku, status);
        }
    }

    // ------------------ 查询方法（获取信息）-----------------
    // 提供对内部状态的受控访问，而非简单暴露字段

    public String getId() { return id; }
    public String getSku() { return sku; }
    public String getName() { return name; }
    public String getDescription() { return description; }
    public double getPrice() { return price; }
    public int getStockQuantity() { return stockQuantity; }
    public boolean isActive() { return active; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public LocalDateTime getLastUpdatedAt() { return lastUpdatedAt; }

    /**
     * 业务判断方法：是否库存偏低？
     */
    public boolean isLowStock() {
        return stockQuantity <= LOW_STOCK_THRESHOLD;
    }

    /**
     * 计算产品价值（库存 * 单价）。这是一个衍生业务属性。
     */
    public double calculateInventoryValue() {
        return price * stockQuantity;
    }

    // ------------------ 私有辅助方法 ------------------------
    // 将重复的验证和工具逻辑封装起来，保持公共方法简洁

    private void updateTimestamp() {
        this.lastUpdatedAt = LocalDateTime.now();
    }

    private String validateSku(String sku) {
        // 简单的SKU格式验证（例如：必须为字母数字，长度8-15）
        if (!sku.matches("^[A-Z0-9]{8,15}$")) {
            throw new IllegalArgumentException("SKU格式无效。必须为8-15位大写字母或数字。输入: " + sku);
        }
        return sku;
    }

    private String validateName(String name) {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("产品名称不能为空");
        }
        if (name.length() > 200) {
            throw new IllegalArgumentException("产品名称长度不能超过200个字符");
        }
        return name.trim();
    }

    private double validatePrice(double price) {
        if (price < MIN_PRICE) {
            throw new IllegalArgumentException(
                String.format("价格必须大于等于 %.2f。输入价格: %.2f", MIN_PRICE, price)
            );
        }
        // 可以添加更多规则，如最大价格、精度限制等
        return Math.round(price * 100.0) / 100.0; // 四舍五入到分
    }

    private int validateStock(int stock) {
        if (stock < MIN_STOCK) {
            throw new IllegalArgumentException("库存数量不能为负数。输入: " + stock);
        }
        return stock;
    }

    // ------------------ 重写 Object 方法 --------------------
    // 确保对象在集合中正确工作，并支持调试

    @Override
    public boolean equals(Object o) {
        // 业务上，通常使用唯一业务标识（如id或sku）来判断相等性
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        Product product = (Product) o;
        return id.equals(product.id); // 基于ID的相等性
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    @Override
    public String toString() {
        // 提供有信息量的字符串表示，便于日志记录和调试
        return String.format(
            "Product{id='%s', sku='%s', name='%s', price=%.2f, stock=%d, active=%s}",
            id, sku, name, price, stockQuantity, active
        );
    }
}
```

### 关键设计要点与业务价值分析：

1.  **封装与不变性**：
    *   `id`, `sku`, `createdAt` 被声明为 `final`。这确保了核心业务标识的不可变性，对于哈希、缓存和并发访问至关重要。
    *   所有状态都通过方法（Getter/Setter）进行访问和修改，内部验证逻辑得以强制执行。

2.  **“创建即有效”原则**：
    *   构造函数中集成了严格的验证逻辑。一个`Product`对象一旦被成功创建，它就处于一个**有效、一致的业务状态**。这消除了整个系统中散布的验证代码。

3.  **丰富的业务行为**：
    *   类中包含了`reduceStock`、`replenishStock`、`updatePrice`等方法。这些不是简单的Setter，而是封装了完整业务规则（如检查库存不足、触发低库存警报）的**领域行为**。这避免了“贫血模型”问题，使业务逻辑高内聚。

4.  **多种构造策略**：
    *   **全参构造**：用于从数据库等持久化存储中完整重建对象。
    *   **业务构造**：用于通过业务人员提供的参数创建新对象，内部处理ID生成和时间戳。
    *   这种分离清晰地区分了“对象创建”和“对象重建”的上下文。

5.  **清晰的静态常量**：
    *   `MIN_PRICE`、`LOW_STOCK_THRESHOLD`等常量将业务规则显式化、集中化。修改阈值只需改动一处。

6.  **防御性编程与优雅的错误处理**：
    *   使用`Objects.requireNonNull`防止空值。
    *   自定义验证方法提供明确、可操作的异常信息，便于问题追踪和调试。

7.  **对标准方法的覆盖**：
    *   重写`equals`/`hashCode`（基于业务ID）确保对象在`HashSet`或`HashMap`中行为正确。
    *   重写`toString`提供有意义的调试信息。

### 使用示例：

```java
public class ProductDemo {
    public static void main(String[] args) {
        // 1. 通过业务构造函数创建新产品
        Product laptop = new Product("LT-2024-X1", "高性能笔记本电脑", 
                                    "搭载最新处理器，适合开发和游戏", 1299.99, 50);

        System.out.println("创建产品: " + laptop);
        System.out.println("库存价值: $" + laptop.calculateInventoryValue());

        // 2. 执行业务操作
        try {
            laptop.reduceStock(3); // 成功售出3台
            System.out.println("售出3台后库存: " + laptop.getStockQuantity());

            laptop.reduceStock(48); // 这将触发低库存警告
            System.out.println("当前是否低库存? " + laptop.isLowStock());

            // laptop.reduceStock(10); // 这将抛出异常：库存不足

        } catch (IllegalArgumentException | IllegalStateException e) {
            System.err.println("业务操作失败: " + e.getMessage());
        }

        // 3. 更新价格
        laptop.updatePrice(1199.99);

        // 4. 补货
        laptop.replenishStock(30);
        System.out.println("补货后库存: " + laptop.getStockQuantity());
    }
}
```

