func allSubstrings(of inputString: String) -> [String] {
    let length = inputString.count
    var substrings: [String] = []

    for i in 0..<length {
        for j in (i + 1)...length {
            let start = inputString.index(inputString.startIndex, offsetBy: i)
            let end = inputString.index(inputString.startIndex, offsetBy: j)
            substrings.append(String(inputString[start..<end]))
        }
    }
    return substrings
}

func longestCommonSubstring(in strings: [String], minOccurrence k: Int) -> String? {
    guard !strings.isEmpty else { return nil }

    var longestFound = ""

    for string in strings {
        let substrings = allSubstrings(of: string)

        for substring in substrings {
            var occurrenceCount = 0

            for otherString in strings {
                if otherString.contains(substring) {
                    occurrenceCount += 1
                }
            }

            if occurrenceCount >= k && substring.count > longestFound.count {
                longestFound = substring
            }
        }
    }

    return longestFound.isEmpty ? nil : longestFound
}
```

