function sortBooks(books) {
    // Create a copy to avoid mutating the original array
    const booksCopy = [...books];

    // Custom comparison function
    booksCopy.sort((a, b) => {
        // Get first character of each string
        const firstCharA = a.charAt(0);
        const firstCharB = b.charAt(0);

        // Check if first character is a digit
        const isDigitA = /\d/.test(firstCharA);
        const isDigitB = /\d/.test(firstCharB);

        // Rule: numbers before letters
        if (isDigitA && !isDigitB) return -1;
        if (!isDigitA && isDigitB) return 1;

        // If both start with digits or both with non-digits, compare first character
        if (firstCharA !== firstCharB) {
            return firstCharA < firstCharB ? -1 : 1;
        }

        // Same first character, compare lengths in descending order
        if (a.length !== b.length) {
            return b.length - a.length;
        }

        // Same first character and same length, compare ASCII values in descending order
        // This means compare the whole strings lexicographically in reverse
        if (a !== b) {
            return a > b ? -1 : 1;
        }

        // If identical strings, keep original order (stable sort)
        return 0;
    });

    return booksCopy;
}

