## Method 3: Complete Class with Error Handling

```cpp
#include <wx/grid.h>
#include <wx/msgdlg.h>

class GridHelper
{
private:
    wxGrid* m_grid;
    std::unordered_map<wxString, int> m_columnCache;
    bool m_cacheValid;

public:
    GridHelper(wxGrid* grid) : m_grid(grid), m_cacheValid(false) {}

    // Get cell value by column label
    wxString GetCellValue(const wxString& columnLabel, int row)
    {
        if (!m_grid)
        {
            wxMessageBox("Grid is not initialized", "Error", wxOK | wxICON_ERROR);
            return wxEmptyString;
        }

        int col = GetColumnIndex(columnLabel);
        if (col == -1)
        {
            wxMessageBox(wxString::Format("Column '%s' not found", columnLabel), 
                        "Error", wxOK | wxICON_ERROR);
            return wxEmptyString;
        }

        if (row < 0 || row >= m_grid->GetNumberRows())
        {
            wxMessageBox(wxString::Format("Row %d is out of range", row), 
                        "Error", wxOK | wxICON_ERROR);
            return wxEmptyString;
        }

        return m_grid->GetCellValue(row, col);
    }

    // Get column index by label
    int GetColumnIndex(const wxString& columnLabel)
    {
        if (!m_cacheValid)
        {
            BuildColumnCache();
        }

        auto it = m_columnCache.find(columnLabel);
        if (it != m_columnCache.end())
        {
            return it->second;
        }

        return -1; // Column not found
    }

    // Rebuild cache (call when grid structure changes)
    void RebuildCache()
    {
        m_cacheValid = false;
    }

private:
    void BuildColumnCache()
    {
        m_columnCache.clear();

        if (!m_grid) return;

        for (int col = 0; col < m_grid->GetNumberCols(); col++)
        {
            wxString label = m_grid->GetColLabelValue(col);
            if (!label.IsEmpty())
            {
                m_columnCache[label] = col;
            }
        }

        m_cacheValid = true;
    }
};
```

