import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

/**
 * Caches the received thumbnail image.
 * @param fileInfo the information about the file
 * @param inputStream the input stream containing the thumbnail image data
 * @throws IOException if an I/O error occurs
 */
public static void cacheReceiveThumb(BaseFileInfo fileInfo, InputStream inputStream) throws IOException {
    if (fileInfo == null || inputStream == null) {
        return;
    }

    // Cache to store thumbnail hashes and their corresponding file paths
    // Using a static map to persist across method calls
    static Map<String, String> thumbnailCache = new HashMap<>();

    boolean isContain = false;

    try {
        // Read the input stream into a byte array
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] data = new byte[4096];
        int bytesRead;

        while ((bytesRead = inputStream.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, bytesRead);
        }

        byte[] thumbnailData = buffer.toByteArray();
        buffer.close();

        // Generate a hash for the thumbnail to check for duplicates
        String thumbnailHash = generateHash(thumbnailData);

        // Check if this thumbnail already exists in cache
        isContain = thumbnailCache.containsValue(thumbnailHash);

        if (!isContain) {
            // Generate a unique cache key for this file
            String cacheKey = generateCacheKey(fileInfo);

            // Store the thumbnail in cache
            thumbnailCache.put(cacheKey, thumbnailHash);

            // Save the thumbnail data to persistent storage
            saveThumbnailToStorage(cacheKey, thumbnailData);

            // Log or update fileInfo with cache information
            updateFileInfoWithCache(fileInfo, cacheKey);
        } else {
            // Thumbnail already exists, just update the fileInfo with existing cache reference
            String existingCacheKey = findCacheKeyByHash(thumbnailHash);
            updateFileInfoWithCache(fileInfo, existingCacheKey);
        }

    } catch (NoSuchAlgorithmException e) {
        throw new IOException("Failed to generate hash for thumbnail", e);
    } finally {
        // Ensure input stream is closed
        try {
            inputStream.close();
        } catch (IOException e) {
            // Log the error but don't throw
            System.err.println("Failed to close input stream: " + e.getMessage());
        }
    }
}

/**
 * Generates a hash for the thumbnail data to identify duplicates
 */
private static String generateHash(byte[] data) throws NoSuchAlgorithmException {
    MessageDigest digest = MessageDigest.getInstance("SHA-256");
    byte[] hashBytes = digest.digest(data);

    // Convert byte array to hexadecimal string
    StringBuilder hexString = new StringBuilder();
    for (byte b : hashBytes) {
        String hex = Integer.toHexString(0xff & b);
        if (hex.length() == 1) {
            hexString.append('0');
        }
        hexString.append(hex);
    }
    return hexString.toString();
}

/**
 * Generates a unique cache key for the file
 */
private static String generateCacheKey(BaseFileInfo fileInfo) {
    // Combine file properties to create a unique key
    return fileInfo.getName() + "_" + fileInfo.getSize() + "_" + 
           fileInfo.getType() + "_" + System.currentTimeMillis();
}

/**
 * Saves thumbnail data to persistent storage
 */
private static void saveThumbnailToStorage(String cacheKey, byte[] thumbnailData) throws IOException {
    // Define cache directory
    File cacheDir = new File("thumbnail_cache");
    if (!cacheDir.exists()) {
        cacheDir.mkdirs();
    }

    // Create cache file
    File cacheFile = new File(cacheDir, cacheKey + ".thumb");

    try (FileOutputStream fos = new FileOutputStream(cacheFile)) {
        fos.write(thumbnailData);
    }
}

/**
 * Updates file info with cache reference
 */
private static void updateFileInfoWithCache(BaseFileInfo fileInfo, String cacheKey) {
    // Assuming BaseFileInfo has a method to set cache reference
    // If not, you might need to extend the class or use a different approach
    try {
        // Using reflection or a setter method if available
        fileInfo.getClass().getMethod("setThumbnailCacheKey", String.class)
                .invoke(fileInfo, cacheKey);
    } catch (Exception e) {
        // Fallback: store in a separate map if BaseFileInfo can't be modified
        System.err.println("Could not update fileInfo with cache key: " + e.getMessage());
    }
}

/**
 * Finds cache key by thumbnail hash
 */
private static String findCacheKeyByHash(String thumbnailHash) {
    for (Map.Entry<String, String> entry : thumbnailCache.entrySet()) {
        if (entry.getValue().equals(thumbnailHash)) {
            return entry.getKey();
        }
    }
    return null;
}
