            target: &mut Option<(i32, i32)>,
            dirs: &[(char, i32, i32)],
            opposite: &HashMap<char, char>,
        ) {
            // Record current cell's info
            let cost = 0; // cost of current cell is stored when we enter it, not here
            // Actually, we don't know cost of current cell until we move into it.
            // So we store cost when we move into a new cell in the move step.
            // But here in DFS, we already have cost from when we moved here.
            // We'll store cost when we insert into cells at the call site before DFS call.

            if master.is_target() {
                *target = Some((r, c));
            }

            for &(dir, dr, dc) in dirs {
                let nr = r + dr;
                let nc = c + dc;
                if !cells.contains_key(&(nr, nc)) && master.can_move(dir) {
                    let cost = master.move_to(dir);
                    // cost is the cost to enter (nr, nc)
                    cells.insert((nr, nc), (cost, master.is_target()));
                    if master.is_target() {
                        *target = Some((nr, nc));
                    }
                    dfs(nr, nc, master, cells, target, dirs, opposite);
                    // Move back
                    master.move_to(opposite[&dir]);
                }
            }
        }

        // Start cell (0, 0) with cost 0 (we don't pay for start cell)
        cells.insert((0, 0), (0, master.is_target()));
        if master.is_target() {
            target = Some((0, 0));
        }
        dfs(0, 0, master, &mut cells, &mut target, &dirs, &opposite);

        // If target not found
        let target_pos = match target {
            Some(pos) => pos,
            None => return -1,
        };

        // Dijkstra from (0, 0) to target_pos
        let mut dist = HashMap::new();
        let mut heap = BinaryHeap::new();
        dist.insert((0, 0), 0);
        heap.push(Reverse((0, 0, 0))); // (total_cost, r, c)

        while let Some(Reverse((cost, r, c))) = heap.pop() {
            if (r, c) == target_pos {
                return cost;
            }
            if cost > *dist.get(&(r, c)).unwrap_or(&i32::MAX) {
                continue;
            }
            for &(_, dr, dc) in &dirs {
                let nr = r + dr;
                let nc = c + dc;
                if let Some(&(edge_cost, _)) = cells.get(&(nr, nc)) {
                    let new_cost = cost + edge_cost;
                    if new_cost < *dist.get(&(nr, nc)).unwrap_or(&i32::MAX) {
                        dist.insert((nr, nc), new_cost);
                        heap.push(Reverse((new_cost, nr, nc)));
                    }
                }
            }
        }

        -1
    }
}
```

---

## Explanation of the code

1. **DFS exploration**  
   We start at `(0, 0)` and try moving in all four directions.  
   If `canMove` is true and the destination is not visited, we `move`, record its cost and target status, then recurse.  
   After recursion, we move back to the original cell.

2. **Graph building**  
   `cells` maps coordinates to `(cost, is_target)`.  
   We also track the target’s coordinates.

3. **Dijkstra search**  
   We run Dijkstra from `(0, 0)` to the target.  
   Edge weight = cost of entering the neighboring cell.  
   Start node has distance 0 (no cost for starting cell).

4. **Return result**  
   If target unreachable in Dijkstra (shouldn’t happen if found in DFS), return -1.  
   Otherwise, return the minimum cost found.

This ensures we explore all reachable cells, build the graph, and find the cheapest path to the target.

