    resultArray[i][0] := -1;
    resultArray[i][1] := -1;
  end;

  // Precompute using dictionary
  shortest := TDictionary<Integer, TIntArray>.Create;

  try
    // Handle single '0' case
    for i := 0 to n - 1 do
    begin
      if s[i+1] = '0' then
      begin
        if not shortest.ContainsKey(0) then
        begin
          SetLength(arr, 2);
          arr[0] := i;
          arr[1] := i;
          shortest.Add(0, arr);
        end;
        Break;
      end;
    end;

    // Precompute all substrings starting with '1'
    for i := 0 to n - 1 do
    begin
      if s[i+1] = '0' then
        continue;

      val := 0;
      for j := i to n - 1 do
      begin
        val := (val shl 1) or (Ord(s[j+1]) - Ord('0'));

        // Limit value size to avoid overflow (2^30 is enough)
        if val > (1 shl 30) then
          Break;

        if not shortest.ContainsKey(val) then
        begin
          SetLength(arr, 2);
          arr[0] := i;
          arr[1] := j;
          shortest.Add(val, arr);
        end
        else
        begin
          arr := shortest[val];
          if (j - i) < (arr[1] - arr[0]) then
          begin
            arr[0] := i;
            arr[1] := j;
            shortest[val] := arr;
          end;
        end;
      end;
    end;

    // Process queries
    for i := 0 to queryCount - 1 do
    begin
      target := queries[i][0] xor queries[i][1];

      if shortest.ContainsKey(target) then
      begin
        arr := shortest[target];
        resultArray[i][0] := arr[0];
        resultArray[i][1] := arr[1];
      end;
    end;

  finally
    shortest.Free;
  end;

  Result := resultArray;
end;
```

## Complexity Analysis
- **Time Complexity**: O(n² + q) where n is string length and q is number of queries
- **Space Complexity**: O(min(2^30, n²)) for storing substring values

The solution precomputes all possible substring values and their shortest occurrences, then answers each query in O(1) time by looking up the target value.

