We can solve this problem efficiently using a two-pointer approach, leveraging the fact that both arrays are non-increasing. For each index `i` in `nums1`, we want to find the largest index `j` in `nums2` such that `j >= i` and `nums1[i] <= nums2[j]`. The maximum distance is then the maximum of `j - i` over all valid pairs.

Because both arrays are non-increasing, as `i` increases, `nums1[i]` decreases or stays the same. This makes the condition `nums1[i] <= nums2[j]` easier to satisfy for a fixed `j`, meaning the farthest valid `j` for a given `i` is non-decreasing as `i` increases. Therefore, we can iterate through `nums1` with pointer `i`, and for each `i`, we advance pointer `j` in `nums2` as far as possible while the condition holds. We never need to decrease `j`, so the algorithm runs in O(n1 + n2) time.

### Algorithm:
1. Initialize `i = 0`, `j = 0`, and `ans = 0`.
2. While `i < nums1.length`:
   - Ensure `j >= i` (if `j < i`, set `j = i`).
   - While `j < nums2.length` and `nums2[j] >= nums1[i]`, increment `j`.
   - After the loop, `j-1` is the largest valid index for this `i` (if `j-1 >= i`). Update `ans` with `j-1 - i`.
   - Increment `i`.
3. Return `ans`.

### Scala Implementation:
```scala
object Solution {
    def maxDistance(nums1: Array[Int], nums2: Array[Int]): Int = {
        val n1 = nums1.length
        val n2 = nums2.length
        var i = 0
        var j = 0
        var ans = 0

        while (i < n1) {
            // Ensure j is at least i
            if (j < i) j = i

            // Move j forward while condition holds
            while (j < n2 && nums2(j) >= nums1(i)) {
                j += 1
            }

            // Update answer with the farthest valid j for this i
            if (j - 1 >= i) {
                ans = math.max(ans, j - 1 - i)
            }

            i += 1
        }

        ans
    }
}
```

This code iterates through both arrays only once, maintaining two pointers. It correctly handles cases where no valid pair exists (returns 0) and efficiently computes the maximum distance.

In wxWidgets 3.1.4, to get column data from a column label string for a specific row in a wxGrid, you can follow these approaches:

## Method 1: Find Column Index from Label and Get Cell Value

```cpp
#include <wx/grid.h>

// Function to get cell value by column label and row
wxString GetCellValueByColumnLabel(wxGrid* grid, int row, const wxString& columnLabel)
{
    if (!grid) return wxEmptyString;

    // Find the column index from the label
    int colCount = grid->GetNumberCols();
    int targetCol = -1;

    for (int col = 0; col < colCount; ++col)
    {
        if (grid->GetColLabelValue(col) == columnLabel)
        {
            targetCol = col;
            break;
        }
    }

    // If column found, return the cell value
    if (targetCol != -1)
    {
        return grid->GetCellValue(row, targetCol);
    }

    return wxEmptyString;
}
```

## Method 2: More Robust Version with Error Handling

```cpp
#include <wx/grid.h>
#include <wx/log.h>

// Function that returns both success status and value
bool GetCellValueByColumnLabel(wxGrid* grid, int row, 
                               const wxString& columnLabel, 
                               wxString& value)
{
    value = wxEmptyString;

    if (!grid)
    {
        wxLogError("Grid pointer is null");
        return false;
    }

    if (row < 0 || row >= grid->GetNumberRows())
    {
        wxLogError("Row index %d is out of bounds", row);
        return false;
    }

    // Find column by label (case-sensitive)
    int colCount = grid->GetNumberCols();
    int targetCol = -1;

    for (int col = 0; col < colCount; ++col)
    {
        if (grid->GetColLabelValue(col) == columnLabel)
        {
            targetCol = col;
            break;
        }
    }

    if (targetCol == -1)
    {
        // Optionally try case-insensitive search
        for (int col = 0; col < colCount; ++col)
        {
            if (grid->GetColLabelValue(col).Upper() == columnLabel.Upper())
            {
                targetCol = col;
                break;
            }
        }

        if (targetCol == -1)
        {
            wxLogError("Column label '%s' not found", columnLabel);
            return false;
        }
    }

    // Get the cell value
    value = grid->GetCellValue(row, targetCol);
    return true;
}
```

## Method 3: Create a Helper Class

```cpp
class GridHelper
{
public:
    // Get value by column label
    static wxString GetValue(wxGrid* grid, int row, const wxString& colLabel)
    {
        if (!grid) return wxEmptyString;

        int col = GetColumnIndex(grid, colLabel);
        if (col != -1)
        {
            return grid->GetCellValue(row, col);
        }
        return wxEmptyString;
    }

    // Set value by column label
    static bool SetValue(wxGrid* grid, int row, const wxString& colLabel, 
                         const wxString& value)
    {
        if (!grid) return false;

        int col = GetColumnIndex(grid, colLabel);
        if (col != -1)
        {
            grid->SetCellValue(row, col, value);
            return true;
        }
        return false;
    }

    // Get column index from label
    static int GetColumnIndex(wxGrid* grid, const wxString& colLabel, 
                             bool caseSensitive = true)
    {
        if (!grid) return -1;

        for (int col = 0; col < grid->GetNumberCols(); ++col)
        {
            wxString currentLabel = grid->GetColLabelValue(col);

            if (caseSensitive)
            {
                if (currentLabel == colLabel)
                    return col;
            }
            else
            {
                if (currentLabel.Upper() == colLabel.Upper())
                    return col;
            }
        }
        return -1;
    }
};
```

