Here's the Swift translation of your Python code:

```swift
func allSubstrings(_ inputString: String) -> [String] {
    let length = inputString.count
    var result = [String]()

    for i in 0..<length {
        for j in i+1...length {
            let startIndex = inputString.index(inputString.startIndex, offsetBy: i)
            let endIndex = inputString.index(inputString.startIndex, offsetBy: j)
            result.append(String(inputString[startIndex..<endIndex]))
        }
    }

    return result
}

func longestSubstring(_ strings: [String], _ k: Int) -> String? {
    if strings.isEmpty {
        return nil
    }

    var longestStr = ""

    for s in strings {
        for substr in allSubstrings(s) {
            var count = 0
            for string in strings {
                if string.contains(substr) {
                    count += 1
                }
            }

            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }

    return longestStr.isEmpty ? nil : longestStr
}
```

## How It Works:

### 1. **`allSubstrings(_:)` Function**
- **Purpose**: Generates all possible substrings of a given string
- **How it works**:
  - Uses nested loops with indices `i` and `j` to create all substring ranges
  - `i` is the starting index (from 0 to length-1)
  - `j` is the ending index (from i+1 to length)
  - Uses Swift's string indexing (`index(startIndex, offsetBy:)`) to create substring ranges
  - Returns an array of all substrings

**Example**: For "abc", it returns: ["a", "ab", "abc", "b", "bc", "c"]

### 2. **`longestSubstring(_:_:)` Function**
- **Purpose**: Finds the longest substring that appears in at least `k` strings from the input array
- **How it works**:
  1. Returns `nil` immediately if the input array is empty
  2. Iterates through each string in the input array
  3. For each string, generates all its substrings using `allSubstrings(_:)`
  4. For each substring, counts how many strings in the array contain it
  5. Updates `longestStr` if the substring:
     - Appears in at least `k` strings (`count >= k`)
     - Is longer than the current `longestStr`

## Key Differences from Python:

1. **String Indexing**: Swift strings don't support integer indexing like Python. We use `String.Index` instead:
   ```swift
   // Python equivalent: input_string[i:j]
   let startIndex = inputString.index(inputString.startIndex, offsetBy: i)
   let endIndex = inputString.index(inputString.startIndex, offsetBy: j)
   let substring = String(inputString[startIndex..<endIndex])
   ```

2. **Character Count**: Uses `.count` property instead of `len()` function

3. **Empty String Check**: Uses `.isEmpty` instead of comparing with empty string

4. **Optional Return Type**: `String?` instead of `Optional[str]`

## Time Complexity:
- This algorithm has O(n³) complexity in the worst case (nested loops + substring generation + string contains check)
- For longer strings or larger arrays, you might want to optimize with more efficient algorithms (like using a trie or suffix tree)

## Example Usage:
```swift
let strings = ["ab", "bc", "abc"]
if let result = longestSubstring(strings, 2) {
    print(result) // Output: "b" (or "a", "c", "ab", or "bc" depending on iteration order)
}
```

Note: If multiple substrings have the same maximum length, the function returns the first one encountered during iteration.

以下是一个Java类的示例，展示如何创建具有多个属性、多个构造函数和方法的`Car`类：

```java
// Car类示例
public class Car {
    // 属性（字段）
    private String brand;
    private String model;
    private int year;
    private double price;
    private boolean isRunning;

    // 构造函数1：无参构造函数（默认值）
    public Car() {
        this.brand = "Unknown";
        this.model = "Unknown";
        this.year = 2023;
        this.price = 0.0;
        this.isRunning = false;
        System.out.println("创建了一辆默认汽车");
    }

    // 构造函数2：带部分参数的构造函数
    public Car(String brand, String model, int year) {
        this.brand = brand;
        this.model = model;
        this.year = year;
        this.price = 0.0;  // 默认价格
        this.isRunning = false;  // 默认未启动
        System.out.println("创建了一辆" + brand + " " + model);
    }

    // 构造函数3：带所有参数的构造函数
    public Car(String brand, String model, int year, double price, boolean isRunning) {
        this.brand = brand;
        this.model = model;
        this.year = year;
        this.price = price;
        this.isRunning = isRunning;
        System.out.println("创建了一辆" + brand + " " + model + "，价格: ¥" + price);
    }

    // 方法1：启动汽车
    public void start() {
        if (!isRunning) {
            isRunning = true;
            System.out.println(brand + " " + model + " 已启动");
        } else {
            System.out.println(brand + " " + model + " 已经在运行中");
        }
    }

    // 方法2：停止汽车
    public void stop() {
        if (isRunning) {
            isRunning = false;
            System.out.println(brand + " " + model + " 已停止");
        } else {
            System.out.println(brand + " " + model + " 已经停止");
        }
    }

    // 方法3：汽车鸣笛
    public void honk() {
        System.out.println(brand + " " + model + " 正在鸣笛：嘟嘟！");
    }

    // 方法4：加速
    public void accelerate(int speedIncrease) {
        System.out.println(brand + " " + model + " 加速了 " + speedIncrease + " km/h");
    }

    // 方法5：显示汽车信息
    public void displayInfo() {
        System.out.println("=== 汽车信息 ===");
        System.out.println("品牌: " + brand);
        System.out.println("型号: " + model);
        System.out.println("年份: " + year);
        System.out.println("价格: ¥" + price);
        System.out.println("状态: " + (isRunning ? "运行中" : "已停止"));
        System.out.println("================");
    }

    // 方法6：计算汽车年龄
    public int calculateAge(int currentYear) {
        return currentYear - year;
    }

    // Getter和Setter方法
    public String getBrand() {
        return brand;
    }

    public void setBrand(String brand) {
        this.brand = brand;
    }

    public String getModel() {
        return model;
    }

    public void setModel(String model) {
        this.model = model;
    }

    public int getYear() {
        return year;
    }

    public void setYear(int year) {
        if (year > 1885 && year <= 2024) {  // 简单验证
            this.year = year;
        } else {
            System.out.println("无效的年份");
        }
    }

    public double getPrice() {
        return price;
    }

    public void setPrice(double price) {
        if (price >= 0) {
            this.price = price;
        } else {
            System.out.println("价格不能为负数");
        }
    }

    public boolean isRunning() {
        return isRunning;
    }

    // 静态方法：显示汽车类别
    public static void displayCarCategory() {
        System.out.println("这是一个汽车类，用于表示各种汽车");
    }

    // 重写toString方法
    @Override
    public String toString() {
        return brand + " " + model + " (" + year + ")";
    }
}

